<script setup lang="ts">
import { computed } from 'vue'
import SongCover from './SongCover.vue'
import { ElButton, ElIcon } from 'element-plus'
import { VideoPlay } from '@element-plus/icons-vue'
import { needsSongReview, songReviewLabel } from '../presentation'
import { songTitle, songArtists } from '../../metadata/utils'
import type { MediaSong } from '../../media-library/types'
import type { Tag } from '../../classification/types'
import { confirmedField, fileFormat, fileSize, platformDuration, songTags, displayTime, languageLabels, versionLabels, type SongColumn } from '../presentation'
const props = defineProps<{ items: MediaSong[]; tags: Tag[]; columns: SongColumn[]; compact: boolean; selectionMode: boolean; selectedIds: string[] }>()
defineEmits<{ detail: [song: MediaSong]; play: [song: MediaSong]; review: [song: MediaSong]; select: [song: MediaSong, checked: boolean]; selectPage: [checked: boolean] }>()
const widths: Record<SongColumn, number> = { album: 150, classification: 150, file: 105, location: 180, status: 135, parsed: 165, timestamps: 165 }
const minWidth = computed(() => 405 + props.columns.reduce((sum, column) => sum + widths[column], 0) + (props.selectionMode ? 42 : 0))
const selectedCount = computed(() => props.items.filter(song => props.selectedIds.includes(song.id)).length)
const allSelected = computed(() => !!props.items.length && selectedCount.value === props.items.length)
</script>
<template>
  <div class="library-table-scroll" :class="{ compact, selecting: selectionMode }" tabindex="0" role="region" aria-label="歌曲明细表，可横向滚动">
    <table class="library-table" :style="{ minWidth: `${minWidth}px` }"><caption class="sr-only">歌曲明细：歌曲、专辑、分类、文件和来源信息</caption><colgroup><col v-if="selectionMode" style="width:42px"><col style="width:260px"><col v-if="columns.includes('album')" style="width:150px"><col v-if="columns.includes('classification')" style="width:150px"><col v-if="columns.includes('file')" style="width:105px"><col v-if="columns.includes('location')" style="width:180px"><col v-if="columns.includes('status')" style="width:135px"><col v-if="columns.includes('parsed')" style="width:165px"><col v-if="columns.includes('timestamps')" style="width:165px"><col style="width:145px"></colgroup>
      <thead><tr><th v-if="selectionMode" class="selection-column"><input type="checkbox" aria-label="选择本页全部歌曲" :checked="allSelected" :indeterminate="selectedCount > 0 && !allSelected" @change="$emit('selectPage', ($event.target as HTMLInputElement).checked)"></th><th class="identity-column" scope="col">歌曲 / 歌手</th><th v-if="columns.includes('album')" scope="col">专辑 / 发行信息</th><th v-if="columns.includes('classification')" scope="col">分类标签</th><th v-if="columns.includes('file')" scope="col">文件</th><th v-if="columns.includes('location')" scope="col">媒体库</th><th v-if="columns.includes('status')" scope="col">整理状态</th><th v-if="columns.includes('parsed')" scope="col">文件名解析</th><th v-if="columns.includes('timestamps')" scope="col">扫描 / 修改时间</th><th class="actions-column" scope="col">操作</th></tr></thead>
      <tbody><tr v-for="song in items" :key="song.id" :class="{ selected: selectedIds.includes(song.id) }"><td v-if="selectionMode" class="selection-column"><input type="checkbox" :aria-label="`选择 ${songTitle(song)}`" :checked="selectedIds.includes(song.id)" @change="$emit('select', song, ($event.target as HTMLInputElement).checked)"></td>
        <td class="identity-column"><div class="table-song-identity"><SongCover :song="song" /><div class="table-song-text"><button class="table-song-title" :title="songTitle(song)" @click="$emit('detail', song)">{{ songTitle(song) }}</button><span class="table-subline" :title="songArtists(song).join('、')">{{ songArtists(song).join('、') || '歌手未识别' }}<span v-if="song.result.songCode" class="song-code"> · 编号 {{ song.result.songCode }}</span></span></div></div></td>
        <td v-if="columns.includes('album')"><span class="cell-primary ellipsis" :title="String(confirmedField(song, 'album') || '')" :class="{ muted: !confirmedField(song, 'album') }">{{ confirmedField(song, 'album') || '专辑未补充' }}</span><span v-if="confirmedField(song, 'releaseDate') || platformDuration(song)" class="table-subline album-details"><span v-if="confirmedField(song, 'releaseDate')">{{ confirmedField(song, 'releaseDate') }}</span><span v-if="platformDuration(song)">时长 {{ platformDuration(song) }}</span></span></td>
        <td v-if="columns.includes('classification')"><div v-if="songTags(song, tags).length" class="table-classifications"><span v-for="tag in songTags(song, tags).slice(0, 3)" :key="tag.id" class="classification-chip" :class="{ inactive: !tag.active }" :title="`${tag.dimension} · ${tag.name}${tag.locked ? ' · 已锁定' : ''}${!tag.active ? ' · 未启用或未加载' : ''}`">{{ tag.name }}</span><span v-if="songTags(song, tags).length > 3" class="classification-more" :title="songTags(song, tags).map(t => `${t.dimension}：${t.name}`).join('；')">+{{ songTags(song, tags).length - 3 }}</span></div><span v-else class="muted">尚未分类</span></td>
        <td v-if="columns.includes('file')"><span class="file-format">{{ fileFormat(song) }}</span><span class="table-subline">{{ fileSize(song.fileSize) }}</span></td>
        <td v-if="columns.includes('location')"><span class="cell-primary ellipsis" :title="song.sourceName">{{ song.sourceName }}</span><span class="table-subline ellipsis" :title="song.relativePath">{{ song.relativePath }}</span></td>
        <td v-if="columns.includes('status')"><span class="state-line" :class="needsSongReview(song) ? 'warning' : 'success'"><i />{{ songReviewLabel(song) }}</span><span class="state-line" :class="song.metadata?.stale ? 'warning' : song.metadata?.fields.length ? 'success' : 'muted'"><i />{{ song.metadata?.stale ? '元数据需重审' : Object.values(song.metadata?.origins ?? {}).some(origin => origin.kind === 'FILE') ? '优先使用文件内嵌信息' : Object.values(song.metadata?.origins ?? {}).some(origin => origin.kind === 'SHARED') ? '来自共享索引' : song.metadata?.fields.length ? `已确认 ${song.metadata.fields.length} 项信息` : '元数据未确认' }}</span></td>
        <td v-if="columns.includes('parsed')"><span class="cell-primary">{{ languageLabels[song.result.language] || song.result.language }} · {{ versionLabels[song.result.versionType] || song.result.versionType }}</span><span class="table-subline">{{ song.result.qualityTags.join(' · ') || '无清晰度标签' }}</span><small class="parse-note">由文件名提取</small></td>
        <td v-if="columns.includes('timestamps')"><span class="table-time" :title="song.scannedAt">{{ displayTime(song.scannedAt) }}</span><span class="table-subline" :title="song.modifiedAt || ''">修改 {{ displayTime(song.modifiedAt) }}</span></td>
        <td class="actions-column"><div class="table-actions"><ElButton text size="small" type="primary" :aria-label="`播放 ${songTitle(song)}`" @click="$emit('play', song)"><ElIcon><VideoPlay /></ElIcon>播放</ElButton><ElButton text size="small" :type="needsSongReview(song) ? 'warning' : 'default'" @click="$emit('review', song)">{{ needsSongReview(song) ? '复核' : '编辑' }}</ElButton><ElButton text size="small" @click="$emit('detail', song)">详情</ElButton></div></td>
      </tr></tbody>
    </table>
  </div>
</template>
<style scoped>
