nt-primary);outline-offset:3px}.table-song-identity{display:flex;align-items:center;gap:10px}.table-song-text{min-width:0;flex:1}.song-code{font-size:10px}.album-details{display:flex!important;flex-wrap:wrap;column-gap:8px;row-gap:0}.table-subline{display:block;font-size:11px;color:var(--sv-text-secondary);margin-top:4px;overflow-wrap:anywhere}.cell-primary{display:block;font-size:12px;overflow-wrap:anywhere}.ellipsis{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.muted{color:var(--sv-text-tertiary)}.file-format{display:inline-block;font:600 11px var(--sv-font-mono);padding:1px 6px;background:var(--sv-surface-3);border-radius:4px;color:var(--sv-text-secondary)}.table-classifications{display:flex;gap:4px;flex-wrap:wrap}.classification-chip{display:inline-block;max-width:86px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;background:var(--sv-accent-soft);color:var(--sv-accent-primary);padding:1px 6px;border-radius:4px;font-size:10px}.classification-chip.inactive{background:var(--sv-surface-3);color:var(--sv-text-secondary)}.classification-more{color:var(--sv-text-secondary);font-size:10px;padding:2px}.state-line{display:flex;gap:6px;align-items:center;font-size:10px;white-space:nowrap}.state-line+.state-line{margin-top:5px}.state-line i{width:5px;height:5px;border-radius:50%;background:currentColor;flex-shrink:0}.warning{color:var(--el-color-warning-dark-2)}.success{color:var(--sv-accent-primary)}.table-actions{display:flex;align-items:center;gap:0;white-space:nowrap}.table-actions .el-button{margin:0;padding:5px 4px;height:28px;font-size:11px}.table-actions .el-icon{margin-right:3px}.parse-note{display:block;font-size:10px;color:var(--sv-text-tertiary);margin-top:4px}.table-time{display:block;font-size:11px;color:var(--sv-text-secondary);white-space:nowrap}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
